const D = { scale:1, energy:.7, speed:1, mane:.6, density:.5, hue:22, x:.5, y:.66, pose:'gallop', style:'woodblock', act:'free', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7) * 43758.5453; return s - Math.floor(s); };
const TAU = Math.PI * 2;
const clamp = (v,a,b) => v < a ? a : v > b ? b : v;
const u = Math.min(width, height);
const sf = (u * P.scale) / 1000;               // design units -> px; horse ~520 tall => ~0.5u
const E = P.energy;
const H = ((P.hue % 360) + 360) % 360;
const style = P.style;
const dens = P.density;
const bt = K.beat * P.speed;

// seeded strand/hatch/dust tables
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  S.mane = []; for (let i = 0; i < 15; i++) S.mane.push({ o: fr(i*3+1), l: 0.7 + fr(i*3+2)*0.6, w: 0.6 + fr(i*3+3)*0.8 });
  S.tail = []; for (let i = 0; i < 11; i++) S.tail.push({ o: fr(i*5+40), l: 0.75 + fr(i*5+41)*0.5, w: 0.5 + fr(i*5+42)*0.9 });
  S.hatch = []; for (let i = 0; i < 22; i++) S.hatch.push({ x: fr(i*7+9)*2-1, y: fr(i*7+10)*2-1, a: fr(i*7+11), l: 0.4+fr(i*7+12)*0.6 });
}
if (!S.dust) S.dust = [];
if (S.lastBeat == null || K.beat < S.lastBeat) S.lastBeat = K.beat;

// ---- pose / act resolution ----
let pose = P.pose;
if (P.act === 'journey') pose = ['idle','trot','gallop','gallop','trot','gallop','rear','idle'][K.section % 8];
else if (P.act === 'spook') pose = (K.intensity > 0.82) ? 'rear' : (K.intensity > 0.5 ? 'gallop' : 'trot');

// gait constants
const G = ({
  gallop: { rate:1.0, swing:0.62, knee:0.9, bounce:1.0, pitch:0.13, surge:0.05, stream:1.0, up:0.0 },
  trot:   { rate:1.15, swing:0.42, knee:0.6, bounce:0.5, pitch:0.05, surge:0.02, stream:0.55, up:0.0 },
  rear:   { rate:0.5, swing:0.3, knee:0.7, bounce:0.25, pitch:0.0, surge:0.0, stream:0.7, up:1.0 },
  idle:   { rate:0.5, swing:0.12, knee:0.35, bounce:0.12, pitch:0.02, surge:0.0, stream:0.25, up:0.0 }
})[pose] || { rate:1, swing:0.5, knee:0.8, bounce:0.8, pitch:0.1, surge:0.04, stream:0.8, up:0 };

const sp = bt * G.rate;                          // stride clock
const strideP = sp - Math.floor(sp);             // 0..1 within stride
const kick = K.pulse * 0.6 + A.bass * 0.9;

// body dynamics (px) — the silhouette-displacing baseline
const bAmp = u * (0.028 + 0.075 * E) * G.bounce;
let bounce = -bAmp * (0.62 * Math.sin(strideP * TAU) + 0.38 * Math.sin(strideP * 2 * TAU));
let surge = Math.sin(strideP * TAU) * u * 0.035 * G.surge * (0.6 + E);
let pitch = Math.sin(strideP * TAU + 0.6) * G.pitch * (0.5 + 0.6 * E);
// rear: raise front, pitch back, rhythmic paw
let rearLift = 0;
if (pose === 'rear') { const r = 0.5 + 0.5 * Math.sin(sp * TAU * 0.5); rearLift = r; pitch = -0.55 * r; bounce = -u * 0.03 * r; }
if (pose === 'idle') { surge = Math.sin(K.t * 1.1) * u * 0.006; pitch = Math.sin(K.t * 0.7) * 0.02; }

const px = P.x * width + surge + A.lowmid * u * 0.02 * Math.sin(K.t * 4);
const py = P.y * height + bounce;

// grazing head dip (idle) on alternating beats
const graze = pose === 'idle' ? clamp(Math.sin(bt * 0.5 * TAU), 0, 1) : 0;

push();
translate(px, py);
rotate(pitch);
scale(sf);
// face left; flip so P.x still means anchor. (keep facing left)

// ============ palette ============
const bodyH = H, bodyS = style === 'sumi' ? 0 : 46, bodyB = style === 'silhouette' ? 10 : 62;
const inkH = 20, inkS = style === 'neon' ? 70 : 16, inkB = style === 'neon' ? 100 : 9;
const shadowB = bodyB - 22;

// ---- anatomical key points (local units, origin=barrel center) ----
const NECK = { x: -300, y: -70 };                // neck base (shoulder top)
let neckAng = -0.55 + graze * 1.35 - G.up * 0.5; // radians from +x axis, head direction
const neckLen = 250;
const head = { x: NECK.x + Math.cos(Math.PI + neckAng) * neckLen, y: NECK.y + Math.sin(Math.PI + neckAng) * neckLen };
// legs anchors
const shoulder = { x: -215, y: 40 };
const hip = { x: 235, y: 30 };
const groundReach = 250;

// ---- leg solver ----
function legPoints(hx, hy, phase, front) {
  const dir = front ? -1 : 1;
  const th1 = 0.02 + dir * (G.swing) * Math.sin(phase * TAU) * (0.6 + 0.7 * E);
  const kneePh = front ? 1.2 : 1.6;
  const flex = G.knee * Math.max(0, Math.sin(phase * TAU + kneePh)) * (0.5 + 0.8 * E);
  const upLen = groundReach * 0.5, loLen = groundReach * 0.52;
  const kx = hx + Math.sin(th1) * upLen, ky = hy + Math.cos(th1) * upLen;
  const th2 = th1 + flex * (front ? -1 : 1) * 0.9 - 0.15;
  const hox = kx + Math.sin(th2) * loLen, hoy = ky + Math.cos(th2) * loLen;
  return { hx, hy, kx, ky, hox, hoy, planted: Math.cos(phase * TAU) < -0.2 };
}
// phase offsets per gait
let offFN, offFF, offHN, offHF;
if (pose === 'trot') { offFN = 0.0; offHF = 0.0; offFF = 0.5; offHN = 0.5; }
else { offHN = 0.0; offHF = 0.12; offFN = 0.5; offFF = 0.62; }
let rearPawN = 0, rearPawF = 0;
if (pose === 'rear') { rearPawN = rearLift; rearPawF = rearLift * 0.85; }

function drawLeg(pt, near, front) {
  const wgt = (near ? 30 : 24) * (0.85 + 0.3 * dens);
  const col = near ? shadowB : shadowB - 8;
  if (style === 'silhouette') { stroke(bodyH, bodyS, bodyB); }
  else if (style === 'neon') { stroke(inkH, inkS, inkB, 90); drawingContext.shadowBlur = 10 * P.scale; drawingContext.shadowColor = 'hsla(' + inkH + ',80%,55%,0.8)'; }
  else if (style === 'sumi') { stroke(0, 0, near ? 12 : 22); }
  else { stroke(bodyH, bodyS + 6, col, 100); }
  strokeCap(ROUND); noFill();
  strokeWeight(wgt); line(pt.hx, pt.hy, pt.kx, pt.ky);
  strokeWeight(wgt * 0.72); line(pt.kx, pt.ky, pt.hox, pt.hoy);
  drawingContext.shadowBlur = 0;
  // hoof
  if (style !== 'silhouette') { noStroke(); fill(inkH, 20, style === 'neon' ? 100 : 14); ellipse(pt.hox, pt.hoy, wgt * 1.1, wgt * 0.8); }
}

// ==== far legs first ====
const flFore = legPoints(shoulder.x, shoulder.y, strideP + offFF - (pose === 'rear' ? rearPawF : 0) * 0.0, true);
const flHind = legPoints(hip.x, hip.y, strideP + offHF, false);
// rear: fold forelegs up
if (pose === 'rear') { flFore.kx = shoulder.x - 40; flFore.ky = shoulder.y + 60 - 120 * rearPawF; flFore.hox = shoulder.x - 120; flFore.hoy = shoulder.y - 10 - 200 * rearPawF; }
drawLeg(flHind, false, false);
drawLeg(flFore, false, true);

// ============ MANE + TAIL under-block (drawn behind body for stream) ============
function drawStreamer(rootX, rootY, baseAng, table, lenU, back) {
  const stream = G.stream * (0.6 + 0.9 * E);
  const velWhip = (bounce / u) * 6;
  for (const s of table) {
    const L = lenU * s.l * (0.5 + P.mane);
    const seg = 5;
    let x = rootX, y = rootY, ang = baseAng + (s.o - 0.5) * 0.5;
    if (style === 'neon') { stroke((inkH + 20) % 360, 60, 100, 70); drawingContext.shadowBlur = 8 * P.scale; drawingContext.shadowColor = 'hsla(40,90%,55%,0.7)'; }
    else if (style === 'silhouette') stroke(bodyH, bodyS, bodyB);
    else if (style === 'sumi') stroke(0, 0, 16 + s.o * 18);
    else stroke(bodyH, bodyS + 10, shadowB - 4 + s.o * 20);
    noFill(); strokeCap(ROUND); strokeWeight((14 + s.w * 12) * (0.7 + dens * 0.5));
    beginShape(); vertex(x, y);
    for (let k = 1; k <= seg; k++) {
      const t = k / seg;
      const wob = Math.sin(t * 3 + K.t * 3 + s.o * 6) * (0.35 + stream * 0.5) * t;
      ang = baseAng + (s.o - 0.5) * 0.4 + wob + back * stream * t * 1.1 + velWhip * t * 0.3;
      x += Math.cos(ang) * (L / seg); y += Math.sin(ang) * (L / seg) + t * 6;
      curveVertex(x, y);
    }
    endShape();
    drawingContext.shadowBlur = 0;
  }
}
// tail (from croup, streams back = +x)
drawStreamer(hip.x + 40, hip.y - 40, 0.2, S.tail, 300, 0.9);

// ============ BODY BLOCK (color) with woodblock misregistration ============
function bodyOutline() {
  beginShape();
  vertex(hip.x + 70, -30);                 // croup top
  bezierVertex(120, -150, -120, -160, NECK.x + 40, NECK.y - 20); // topline/back to withers
  // neck front to poll
  bezierVertex(NECK.x - 40, NECK.y - 40, head.x + 70, head.y - 30, head.x + 20, head.y - 40); // up neck to poll
  bezierVertex(head.x - 30, head.y - 30, head.x - 55, head.y + 20, head.x - 30, head.y + 55); // face to muzzle
  bezierVertex(head.x + 10, head.y + 70, head.x + 40, head.y + 55, NECK.x - 30, NECK.y + 120); // jaw down throat
  bezierVertex(NECK.x + 20, NECK.y + 170, shoulder.x - 10, 130, shoulder.x + 40, 150); // chest to under
  bezierVertex(-40, 200, 120, 205, hip.x + 20, 150);   // belly to flank
  bezierVertex(hip.x + 90, 120, hip.x + 100, 20, hip.x + 70, -30); // haunch back to croup
  endShape(CLOSE);
}
const mreg = style === 'woodblock' ? 9 : 0; // misregistration offset (local units)

if (style === 'silhouette') {
  noStroke(); fill(bodyH, bodyS, bodyB); bodyOutline();
} else if (style === 'neon') {
  noFill(); stroke(inkH, inkS, inkB, 95); strokeWeight(9);
  drawingContext.shadowBlur = 16 * P.scale; drawingContext.shadowColor = 'hsla(' + inkH + ',85%,55%,0.85)';
  bodyOutline(); drawingContext.shadowBlur = 0;
} else {
  // color under-block, offset (misregistration for woodblock)
  push(); translate(mreg, mreg * 0.6);
  noStroke();
  if (style === 'sumi') fill(0, 0, 30); else fill(bodyH, bodyS, bodyB);
  bodyOutline();
  pop();
  // carving hatch in shadow zones (belly / lower neck)
  stroke(style === 'sumi' ? color(0, 0, 20, 60) : color(bodyH, bodyS + 10, shadowB - 6, 70));
  strokeWeight(4 + dens * 3);
  const hn = Math.round(8 + dens * 12);
  for (let i = 0; i < hn; i++) {
    const h = S.hatch[i % S.hatch.length];
    const bx = -80 + h.x * 260, by = 120 + h.y * 60;
    line(bx, by, bx + Math.cos(h.a * 3) * 30 * h.l, by + 16 * h.l);
  }
  // ink key-line contour (on top, not offset -> registration gap shows)
  noFill();
  if (style === 'sumi') { stroke(0, 0, 8); strokeWeight(11 + kick * 6); }
  else { stroke(inkH, inkS, inkB); strokeWeight(9); }
  strokeJoin(ROUND); bodyOutline();
  // eye + nostril
  noStroke(); fill(inkH, 30, style === 'sumi' ? 6 : 10);
  ellipse(head.x + 6, head.y - 2, 26, 30);
  ellipse(head.x - 34, head.y + 40, 16, 12);
  if (style !== 'sumi') { fill(45, 20, 96, 80); ellipse(head.x + 1, head.y - 7, 9, 9); }
}

// ============ MANE (over neck, streams back) ============
drawStreamer(head.x + 30, head.y - 25, -0.1 + neckAng * 0.3, S.mane, 150, 0.55);

// ==== near legs (front of body) ====
const nlHind = legPoints(hip.x, hip.y, strideP + offHN, false);
let nlFore = legPoints(shoulder.x, shoulder.y, strideP + offFN, true);
if (pose === 'rear') { nlFore.kx = shoulder.x - 20; nlFore.ky = shoulder.y + 40 - 150 * rearPawN; nlFore.hox = shoulder.x - 150; nlFore.hoy = shoulder.y - 40 - 240 * rearPawN; }
drawLeg(nlHind, true, false);
drawLeg(nlFore, true, true);

pop(); // end horse transform

// ============ DUST puffs on hoof strikes (world space, moving particles) ============
if (pose !== 'idle' && pose !== 'rear') {
  // spawn on stride landings
  if (strideP < (S.lastStrideP == null ? 1 : S.lastStrideP)) {
    const n = 2 + Math.round(dens * 3 + E * 2);
    for (let i = 0; i < n; i++) S.dust.push({ x: px + (fr(i + Math.floor(sp)) - 0.7) * u * 0.12, y: py + u * 0.11 * P.scale, vx: -(0.3 + fr(i * 2) * 0.5) * u * 0.004, vy: -fr(i * 3) * u * 0.003, r: (0.3 + fr(i * 5) * 0.7) * u * 0.03, life: 1 });
  }
}
S.lastStrideP = strideP;
noStroke();
for (let i = S.dust.length - 1; i >= 0; i--) {
  const d = S.dust[i]; d.x += d.vx; d.y += d.vy; d.vy += u * 0.00006; d.life -= 0.03; d.r *= 1.03;
  if (d.life <= 0) { S.dust.splice(i, 1); continue; }
  const a = d.life * 40 * (style === 'neon' ? 0.6 : 1);
  if (style === 'sumi' || style === 'silhouette') fill(0, 0, 55, a);
  else fill(H, 12, 82, a);
  ellipse(d.x, d.y, d.r * 2, d.r * 2);
}
if (S.dust.length > 90) S.dust.splice(0, S.dust.length - 90);

blendMode(BLEND);
